using GameplayCore.Damage; using GameplayCore.Entities; using ZombieWar.Features.Health.Controller; using ZombieWar.Features.Health.Factories; using ZombieWar.Features.Boss.Ports;
namespace ZombieWar.Integration.Boss { public sealed class BossHealthAdapter:IBossHealthPort { private readonly IHealthFactory _factory;private HealthController _health;public BossHealthAdapter(IHealthFactory factory){_factory=factory;}public bool IsAlive=>_health!=null&&_health.IsAlive;public float CurrentHealth=>_health!=null?_health.CurrentHealth:0f;public float MaxHealth=>_health!=null?_health.MaxHealth:0f;public void Initialize(EntityId id,float max)=>_health=_factory.Create(id,max);public void ApplyDamage(DamageInfo damage)=>_health?.ApplyDamage(damage); } }
